1	const PROCESSING_FEE = 5;
2	
3	export type Item = {
4	  type: string;
5	  material?: string;
6	  enchantment?: number;
7	  cursed?: boolean;
8	};
9	
10	// `op` is typed as a plain string because a scenario arrives as untrusted JSON;
11	// the discriminating narrowing happens in `runScenario`.
12	export type QuoteStep = {
13	  op: string;
14	  items: Item[];
15	};
16	
17	export type Damage = {
18	  itemType: string;
19	  amount: number;
20	};
21	
22	export type Incident = {
23	  cause: string;
24	  damages: Damage[];
25	};
26	
27	export type ClaimStep = {
28	  op: string;
29	  policy: number;
30	  incident: Incident;
31	};
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	const isClaimStep = (step: Step): step is ClaimStep => step.op === "claim";
36	
37	export type Customer = {
38	  yearsWithMHPCO: number;
39	};
40	
41	export type Scenario = {
42	  customer: Customer;
43	  steps: Step[];
44	};
45	
46	export type QuoteResult = {
47	  premium: number;
48	};
49	
50	export type ClaimResult = {
51	  payout: number;
52	  remainingCap: number;
53	};
54	
55	export type StepResult = QuoteResult | ClaimResult;
56	
57	export type ScenarioResults = {
58	  results: StepResult[];
59	};
60	
61	const BASE_PREMIUMS: Record<string, number> = {
62	  sword: 100,
63	  amulet: 60,
64	  staff: 80,
65	  potion: 40,
66	  rune: 25,
67	  moonstone: 25,
68	};
69	
70	// Percentages are applied as `amount * percent / 100` rather than
71	// `amount * 1.percent`, so that integer amounts stay exact: 100 * 1.1 is
72	// 110.00000000000001 in binary floating point, while 100 * 10 / 100 is 10.
73	const percentOf = (amount: number, percent: number): number =>
74	  (amount * percent) / 100;
75	
76	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type];
77	
78	const BLOCK_SIZE = 3;
79	const BLOCK_BASE_PREMIUM = 60;
80	
81	// Items of the same type are priced together, so a policy is partitioned into
82	// same-type groups before any group pricing rule is applied.
83	const groupByType = (items: Item[]): Item[][] => {
84	  const groupsByType = new Map<string, Item[]>();
85	  for (const item of items) {
86	    const alike = groupsByType.get(item.type) ?? [];
87	    alike.push(item);
88	    groupsByType.set(item.type, alike);
89	  }
90	  return [...groupsByType.values()];
91	};
92	
93	const sumOf = <T>(values: T[], amount: (value: T) => number): number =>
94	  values.reduce((total, value) => total + amount(value), 0);
95	
96	// A building block of exactly 3 alike components is offered at a flat rate.
97	const groupBasePremium = (alike: Item[]): number =>
98	  alike.length === BLOCK_SIZE
99	    ? BLOCK_BASE_PREMIUM
100	    : sumOf(alike, basePremium);
101	
102	const itemsBasePremium = (items: Item[]): number =>
103	  sumOf(groupByType(items), groupBasePremium);
104	
105	const CURSE_SURCHARGE_PERCENT = 50;
106	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
107	const HIGH_ENCHANTMENT_LEVEL = 5;
108	
109	const isCursed = (item: Item): boolean => item.cursed === true;
110	
111	const isHighlyEnchanted = (item: Item): boolean =>
112	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
113	
114	// Each rule charges its percent of the affected item's own base premium.
115	type ItemSurchargeRule = {
116	  applies: (item: Item) => boolean;
117	  percent: number;
118	};
119	
120	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
121	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
122	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
123	];
124	
125	// Item-specific surcharges apply to the base premium of the affected item.
126	// Several can apply to the same item, so every matching rule is summed.
127	const itemSurcharges = (item: Item): number => {
128	  const base = basePremium(item);
129	  return sumOf(
130	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)),
131	    (rule) => percentOf(base, rule.percent),
132	  );
133	};
134	
135	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
136	const LOYALTY_DISCOUNT_PERCENT = 20;
137	const LOYALTY_YEARS = 2;
138	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
139	
140	const isLongStanding = (customer: Customer): boolean =>
141	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
142	
143	// Who is buying, as opposed to what is being insured. Policy-wide modifiers
144	// depend only on this; item pricing depends only on the items.
145	type Customership = {
146	  customer: Customer;
147	  priorContracts: number;
148	};
149	
150	// Policy-wide modifiers adjust the policy base; item-specific surcharges are
151	// computed against each item's own unmodified base. Both are ADDITIVE against
152	// the base rather than compounding, so they are summed side by side and never
153	// nested inside one another. Discounts are negative percentages.
154	//
155	// Each modifier is written as its own percent-of-the-policy-base summand, so
156	// adding one never changes how the others are computed.
157	const policyModifiers = (
158	  policyBase: number,
159	  { customer, priorContracts }: Customership,
160	): number => {
161	  const firstInsurance = percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
162	  const loyalty = isLongStanding(customer)
163	    ? -percentOf(policyBase, LOYALTY_DISCOUNT_PERCENT)
164	    : 0;
165	  const followUp =
166	    priorContracts > 0
167	      ? -percentOf(policyBase, FOLLOW_UP_DISCOUNT_PERCENT)
168	      : 0;
169	  return firstInsurance + loyalty + followUp;
170	};
171	
172	const policyPremium = (items: Item[], customership: Customership): number => {
173	  const policyBase = itemsBasePremium(items);
174	  return (
175	    policyBase +
176	    policyModifiers(policyBase, customership) +
177	    sumOf(items, itemSurcharges)
178	  );
179	};
180	
181	// Amounts are rounded in the MHPCO's favor, so the direction depends on which
182	// way the money flows: premiums (customer pays) round up. The payout
183	// counterpart rounds down; it is named for its direction for the same reason.
184	const roundUpPremium = (amount: number): number => Math.ceil(amount);
185	
186	const quote = (step: QuoteStep, customership: Customership): QuoteResult => ({
187	  premium: roundUpPremium(
188	    PROCESSING_FEE + policyPremium(step.items, customership),
189	  ),
190	});
191	
192	const INSURANCE_VALUES: Record<string, number> = {
193	  sword: 1000,
194	  amulet: 600,
195	  staff: 800,
196	  potion: 400,
197	  rune: 250,
198	  moonstone: 250,
199	};
200	
201	const insuranceValue = (item: Item): number => INSURANCE_VALUES[item.type];
202	
203	const DEDUCTIBLE = 100;
204	const CAP_MULTIPLE = 2;
205	
206	// A policy, once quoted, carries the cap still available to future claims.
207	type Policy = {
208	  items: Item[];
209	  remainingCap: number;
210	};
211	
212	const openPolicy = (items: Item[]): Policy => ({
213	  items,
214	  remainingCap: CAP_MULTIPLE * sumOf(items, insuranceValue),
215	});
216	
217	const FULL_REIMBURSEMENT_LEVEL = 8;
218	const REDUCED_REIMBURSEMENT_PERCENT = 50;
219	
220	// Damage to a very highly enchanted item is only half reimbursed. The clause
221	// reduces the damage amount; the deductible is taken afterwards.
222	const reimbursedDamage = (amount: number, item: Item): number =>
223	  (item.enchantment ?? 0) >= FULL_REIMBURSEMENT_LEVEL
224	    ? percentOf(amount, REDUCED_REIMBURSEMENT_PERCENT)
225	    : amount;
226	
227	const damagePayout = (damage: Damage, items: Item[]): number => {
228	  const item = items.find((insured) => insured.type === damage.itemType)!;
229	  return reimbursedDamage(damage.amount, item) - DEDUCTIBLE;
230	};
231	
232	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
233	  const payout = sumOf(step.incident.damages, (damage) =>
234	    damagePayout(damage, policy.items),
235	  );
236	  policy.remainingCap -= payout;
237	  return { payout, remainingCap: policy.remainingCap };
238	};
239	
240	export const runScenario = ({
241	  customer,
242	  steps,
243	}: Scenario): ScenarioResults => {
244	  // A claim's `policy` is the zero-based index of the STEP that quoted it, so
245	  // policies are keyed by step index. The customer's prior-contract count is a
246	  // different number — it counts only quote steps — so the two are tracked
247	  // separately.
248	  const policies = new Map<number, Policy>();
249	  let priorContracts = 0;
250	
251	  const results = steps.map((step, index) => {
252	    if (isClaimStep(step)) {
253	      return claim(step, policies.get(step.policy)!);
254	    }
255	    policies.set(index, openPolicy(step.items));
256	    return quote(step, { customer, priorContracts: priorContracts++ });
257	  });
258	
259	  return { results };
260	};
